-- Habilita cambios de terapia futuros sin alterar el historial ni Caja.
begin;
set local lock_timeout='5s';
select pg_advisory_xact_lock(hashtextextended('marathon:master-write:v1',0));
create temporary table _edit_fields_before on commit drop as select jsonb_object_agg(name,jsonb_build_object('count',n,'hash',h))snapshot from(select 'agenda_ajustes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_ajustes" x union all select 'agenda_autorizaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_autorizaciones" x union all select 'agenda_cuotas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_cuotas" x union all select 'agenda_horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_horarios" x union all select 'agenda_pausas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_pausas" x union all select 'agenda_periodos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_periodos" x union all select 'agenda_planes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_planes" x union all select 'agenda_tarifas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_tarifas" x union all select 'anticipo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."anticipo_eventos" x union all select 'anticipos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."anticipos" x union all select 'app_users'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."app_users" x union all select 'attendance_settings'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."attendance_settings" x union all select 'attendance_system_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."attendance_system_audit" x union all select 'bonos_serie'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."bonos_serie" x union all select 'documentos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."documentos" x union all select 'espera'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."espera" x union all select 'horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."horarios" x union all select 'informacion_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."informacion_terapias" x union all select 'master_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."master_audit" x union all select 'movimientos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."movimientos" x union all select 'obras_sociales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."obras_sociales" x union all select 'operation_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."operation_audit" x union all select 'ortopedia_operaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."ortopedia_operaciones" x union all select 'pacientes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."pacientes" x union all select 'productos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."productos" x union all select 'profesional_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."profesional_terapias" x union all select 'profesionales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."profesionales" x union all select 'saldo_ajustes_sesion'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_ajustes_sesion" x union all select 'saldo_aplicaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_aplicaciones" x union all select 'saldo_base_legacy'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_base_legacy" x union all select 'saldo_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_config" x union all select 'saldo_cuentas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_cuentas" x union all select 'saldo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_eventos" x union all select 'saldo_fuentes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_fuentes" x union all select 'saldo_importacion_map'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."saldo_importacion_map" x union all select 'secretarias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."secretarias" x union all select 'sedes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."sedes" x union all select 'shared_space_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."shared_space_config" x union all select 'shared_space_therapies'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."shared_space_therapies" x union all select 'solicitudes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."solicitudes" x union all select 'stock_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."stock_config" x union all select 'terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."terapias" x union all select 'turn_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."turn_audit" x union all select 'turnos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."turnos" x union all select 'user_provision'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."user_provision" x union all select 'user_sedes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."user_sedes" x union all select 'whatsapp_attempts'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."whatsapp_attempts" x union all select 'whatsapp_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."whatsapp_config" x union all select 'whatsapp_events'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."whatsapp_events" x union all select 'whatsapp_message_templates'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."whatsapp_message_templates" x)s;
alter table marathon.agenda_horarios add column terapia_override text references marathon.terapias(id);
alter table marathon.turnos add column terapia_override text references marathon.terapias(id);
CREATE OR REPLACE FUNCTION marathon.agenda_virtual(d date)
 RETURNS TABLE(id text, plan_id uuid, horario_id uuid, dni text, sede text, profesional_id text, terapia_id text, hora time without time zone, duracion_min integer, pausado boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select 'H-'||h.id::text||'-'||d::text,p.id,h.id,p.dni,h.sede,h.profesional_id,coalesce(h.terapia_override,p.terapia_id),h.hora,h.duracion_min,marathon.agenda_pausado(p.id,d)
 from marathon.agenda_horarios h join marathon.agenda_planes p on p.id=h.plan_id
 where h.dia=extract(dow from d)::int and d>=greatest(h.desde,p.inicio) and(h.hasta is null or d<h.hasta) and(p.baja is null or d<p.baja)
 and(p.modalidad<>'sessions' or marathon.agenda_presentes(p.id)<marathon.agenda_total(p.id))
 and not exists(select 1 from marathon.turnos t where t.horario_id=h.id and t.fecha_habitual=d)
$function$
;
CREATE OR REPLACE FUNCTION marathon.turn_series_run(p_request_id text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare result jsonb;info jsonb;t marathon.turnos%rowtype;member marathon.turnos%rowtype;rule marathon.agenda_horarios%rowtype;
 p marathon.agenda_planes%rowtype;before_plan jsonb;changes jsonb;maps jsonb:='{}';ids text[];kind text;scope text;reason text;delta int;new_date date;new_hour time;site text;prof text;new_rule uuid;
 d date;candidate record;occ record;slot jsonb;duration int;count_changed int:=0;after_row jsonb;config jsonb;schedules jsonb;fee numeric;cov jsonb;memo text;qrow marathon.agenda_cuotas%rowtype;quotes_changed int:=0;quotes_kept int:=0;new_therapy text;therapy_minutes int;
begin
 result=marathon.operation_begin(p_request_id,'turn-series',p_data);if result is not null then return result;end if;
 if p_data is null or jsonb_typeof(p_data)<>'object'or exists(select 1 from jsonb_object_keys(p_data)k where k<>all(array['id','action','scope','huella','date','time','site','prof','reason','schedules','amount','coverage','notes','therapy']))then raise exception 'Solicitud inválida.'using errcode='22023';end if;
 kind=p_data->>'action';scope=p_data->>'scope';
 if kind is null or kind not in('cancel','edit')or scope is null or scope not in('single','following')then raise exception 'Elegí la operación y su alcance.'using errcode='22023';end if;
 info=marathon.turn_series_context(p_data->>'id');
 if info->>'huella'is distinct from p_data->>'huella'then raise exception 'La serie cambió. Volvé a abrir el turno para revisar los cambios.'using errcode='PT409';end if;
 select *into strict t from marathon.turnos where id=p_data->>'id'for update;
 reason=btrim(coalesce(nullif(p_data->>'reason',''),'Cancelación o edición manual desde el turno'));
 if length(reason)not between 3 and 1000 then raise exception 'El motivo debe tener entre 3 y 1000 caracteres.'using errcode='22023';end if;
 if t.estado='CANCELADO'or(kind='edit'and t.estado<>'PENDIENTE')then raise exception 'Solo se editan turnos pendientes. Actualizá la agenda.'using errcode='22023';end if;
 if scope='following'and not(info->>'can_following')::boolean then raise exception 'Elegí un turno pendiente de hoy en adelante para cambiar la serie.'using errcode='22023';end if;
 select array_agg(x.id order by x.fecha,x.hora,x.id)into ids from marathon.turnos x where
 case when scope='single'then x.id=t.id else x.fecha>=t.fecha and x.estado='PENDIENTE'and(case when t.plan_id is not null then x.plan_id=t.plan_id else x.plan_id is null and coalesce(x.original_id,x.id)=coalesce(t.original_id,t.id)end)end;
 if cardinality(ids)>2000 then raise exception 'La serie supera 2000 turnos pendientes. Revisala con administración.'using errcode='22023';end if;
 if scope='following'and t.plan_id is not null then
  select *into strict p from marathon.agenda_planes where id=t.plan_id for update;before_plan=to_jsonb(p);
  if p.baja is not null and p.baja<=t.fecha then raise exception 'La asignación ya está dada de baja desde esa fecha.'using errcode='PT409';end if;
  if exists(select 1 from marathon.turnos x where x.plan_id=t.plan_id and x.fecha>=t.fecha and x.estado in('PRESENTE','AUSENTE'))then raise exception 'Hay asistencias registradas desde esa fecha. Elegí un turno posterior o modificá solo este turno.'using errcode='22023';end if;
 end if;
 if kind='cancel'then
  -- Reutilizar el circuito de estado conserva sus controles y libera saldo sin sacar dinero.
  foreach member.id in array ids loop
   select *into member from marathon.turnos where id=member.id;
   perform public.marathon_agenda_command('series-'||md5(p_request_id||member.id),'status',jsonb_build_object('id',member.id,'version',member.version,'estado','CANCELADO'));
   count_changed=count_changed+1;
  end loop;
  if scope='following'and t.plan_id is not null then
   update marathon.agenda_planes set baja=t.fecha where id=t.plan_id;
   update marathon.agenda_periodos set fin=greatest(inicio,t.fecha),anulado=anulado or inicio>=t.fecha where plan_id=t.plan_id and(fin is null or fin>t.fecha);
  end if;
 else
  new_date=marathon.agenda_date(p_data->>'date');
  if p_data?'therapy'then
   new_therapy=marathon.master_text(p_data,'therapy',100,true);
   select duracion_min into therapy_minutes from marathon.terapias where id=new_therapy and estado='ACTIVO';
   if therapy_minutes is null then raise exception 'Seleccioná una terapia activa.'using errcode='22023';end if;
  end if;
  if t.plan_id is not null then select *into strict p from marathon.agenda_planes where id=t.plan_id;end if;
  if p_data?'amount'then
   if coalesce(p_data->>'amount','')!~'^[0-9]{1,10}(\.[0-9]{1,2})?$'then raise exception 'Indicá un importe válido, con hasta dos decimales.'using errcode='22023';end if;
   fee=(p_data->>'amount')::numeric;
   if(p.facturacion='none'and fee<>0)or(p.facturacion='monthly'and fee<=0)then raise exception 'El importe debe respetar la modalidad de pago.'using errcode='22023';end if;
   if p.facturacion='monthly'and scope='single'and fee<>marathon.agenda_tarifa(p.id,t.fecha)then raise exception 'El importe mensual se modifica para la serie. Elegí este turno y los siguientes.'using errcode='22023';end if;
  end if;
  if p_data?'coverage'then cov=marathon.normalize_turn_coverage(t.dni,p_data->'coverage');end if;
  if p_data?'notes'then
   if jsonb_typeof(p_data->'notes')<>'string'or length(p_data->>'notes')>1000 then raise exception 'Las observaciones admiten hasta 1000 caracteres.'using errcode='22023';end if;
   memo=p_data->>'notes';
  end if;
  schedules=p_data->'schedules';delta=new_date-t.fecha;
  if schedules is not null then
   if jsonb_typeof(schedules)<>'array'or jsonb_array_length(schedules)not between 1 and 5 or(select count(distinct x->>'day')from jsonb_array_elements(schedules)x)<>jsonb_array_length(schedules)then raise exception 'Revisá los días de atención.'using errcode='22023';end if;
   for config in select value from jsonb_array_elements(schedules)loop
    if config->>'day'not in('1','2','3','4','5')or config->>'day'is null or coalesce(config->>'time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'or exists(select 1 from jsonb_object_keys(config)k where k<>all(array['day','site','prof','time']))then raise exception 'Revisá días, sede, profesional y hora.'using errcode='22023';end if;
    perform marathon.master_text(config,'site',40,true);perform marathon.master_text(config,'prof',100,true);
   end loop;
  else
   if coalesce(p_data->>'time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'then raise exception 'Elegí una hora válida.'using errcode='22023';end if;
   new_hour=(p_data->>'time')::time;site=marathon.master_text(p_data,'site',40,true);prof=marathon.master_text(p_data,'prof',100,true);
  end if;
  if new_date<marathon.agenda_hoy()or abs(delta)>365 then raise exception 'Elegí una fecha de hoy en adelante, hasta 365 días de diferencia.'using errcode='22023';end if;
  if exists(select 1 from marathon.turnos x where x.id=any(ids)and(x.fecha+delta<marathon.agenda_hoy()or marathon.turn_paid(x.id)>0))then raise exception 'Hay turnos con pagos aplicados o fechas anteriores a hoy. Revisalos antes de editar.'using errcode='22023';end if;
  select coalesce(jsonb_agg(to_jsonb(x)order by x.fecha,x.hora,x.id),'[]')into changes from marathon.turnos x where x.id=any(ids);
  -- Retirar provisionalmente del cupo el conjunto. Toda la operación es atómica.
  update marathon.turnos set estado='CANCELADO'where id=any(ids);
  if scope='following'and t.plan_id is not null then
   for rule in select *from marathon.agenda_horarios x where x.plan_id=t.plan_id and(x.hasta is null or x.hasta>t.fecha)order by x.desde,x.dia,x.id for update loop
    d=greatest(rule.desde,t.fecha);d=d+((rule.dia-extract(dow from d)::int+7)%7);
    if rule.hasta is not null and d>=rule.hasta then continue;end if;
    if schedules is not null then
     select x into config from jsonb_array_elements(schedules)x where(x->>'day')::int=extract(dow from d+delta)::int;
     if config is null then raise exception 'Conservá los días de la serie; la primera fecha desplaza el conjunto.'using errcode='22023';end if;
     site=config->>'site';prof=config->>'prof';new_hour=(config->>'time')::time;
    end if;
    if d+delta<marathon.agenda_hoy()or extract(dow from d+delta)::int not between 1 and 5 then raise exception 'Todos los horarios de la serie deben quedar de lunes a viernes y desde hoy.'using errcode='22023';end if;
    duration=marathon.session_minutes(d+delta,site,prof,new_hour,case when new_therapy is not null and new_therapy<>coalesce(rule.terapia_override,p.terapia_id)then therapy_minutes else rule.duracion_min end);
    update marathon.agenda_horarios set hasta=greatest(desde,t.fecha)where id=rule.id;
    insert into marathon.agenda_horarios(plan_id,sede,profesional_id,dia,hora,duracion_min,desde,hasta,importe_override,coverage_override,observaciones_override,terapia_override)
    values(t.plan_id,site,prof,extract(dow from d+delta)::int,new_hour,duration,d+delta,case when rule.hasta is null then null else rule.hasta+delta end,case when p.facturacion in('class','bonus_class')then coalesce(fee,rule.importe_override)else rule.importe_override end,coalesce(cov,rule.coverage_override),coalesce(memo,rule.observaciones_override),coalesce(new_therapy,rule.terapia_override))returning id into new_rule;
    maps=maps||jsonb_build_object(rule.id::text,new_rule::text);
   end loop;
   -- Conservar las excepciones canceladas: no regenerarlas como turnos nuevos.
   for member in select *from marathon.turnos x where x.plan_id=t.plan_id and x.fecha_habitual>=t.fecha and x.estado='CANCELADO'and not(x.id=any(ids))and maps?x.horario_id::text for update loop
    update marathon.turnos set horario_id=(maps->>member.horario_id::text)::uuid,fecha_habitual=member.fecha_habitual+delta where id=member.id;
    insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data)select p_request_id,auth.uid(),member.id,'series_exception',to_jsonb(member),to_jsonb(x)from marathon.turnos x where x.id=member.id;
   end loop;
  end if;
  for after_row in select value from jsonb_array_elements(changes)loop
   select *into strict member from jsonb_populate_record(null::marathon.turnos,after_row);
   if schedules is not null then
    select x into config from jsonb_array_elements(schedules)x where(x->>'day')::int=extract(dow from((case when scope='single'then member.fecha else coalesce(member.fecha_habitual,member.fecha)end)+delta))::int;
    if config is null then raise exception 'Conservá los días de las sesiones existentes.'using errcode='22023';end if;
    site=config->>'site';prof=config->>'prof';new_hour=(config->>'time')::time;
   end if;
   duration=marathon.session_minutes(member.fecha+delta,site,prof,new_hour,case when new_therapy is not null and new_therapy<>member.terapia_id then therapy_minutes else member.duracion_min end);
   if scope='single'then
    slot=marathon.agenda_cupo(member.fecha+delta,site,prof,coalesce(new_therapy,member.terapia_id),new_hour,null,'H-'||coalesce(member.horario_id::text,'')||'-'||coalesce(member.fecha_habitual::text,''));
   else slot=marathon.agenda_cupo(member.fecha+delta,site,prof,coalesce(new_therapy,member.terapia_id),new_hour,null,'H-'||coalesce(maps->>member.horario_id::text,'')||'-'||coalesce((member.fecha_habitual+delta)::text,''));end if;
   if coalesce((slot->>'blocked')::boolean,true)or coalesce((slot->>'remaining')::int,0)<1 then raise exception 'Sin cupo el % a las %. No se modificó ningún turno.',member.fecha+delta,new_hour using errcode='PT409';end if;
   update marathon.turnos set fecha=member.fecha+delta,hora=new_hour,sede=site,profesional_id=prof,terapia_id=coalesce(new_therapy,member.terapia_id),terapia_override=coalesce(new_therapy,member.terapia_override),duracion_min=duration,estado='PENDIENTE',importe=case when p.facturacion in('monthly','none')then member.importe else coalesce(fee,member.importe)end,coverage=coalesce(cov,member.coverage),booking_notes=coalesce(memo,member.booking_notes),
    horario_id=case when maps?member.horario_id::text then(maps->>member.horario_id::text)::uuid else member.horario_id end,
    fecha_habitual=case when maps?member.horario_id::text then member.fecha_habitual+delta else member.fecha_habitual end,
    fixed_until=case when scope='following'and member.fixed_until is not null then member.fixed_until+delta else member.fixed_until end where id=member.id;
   insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data)select p_request_id,auth.uid(),member.id,'series_edit',after_row,to_jsonb(x)from marathon.turnos x where x.id=member.id;
   count_changed=count_changed+1;
  end loop;
  if scope='following'and t.plan_id is not null then
   if p.facturacion='monthly'and fee is not null then
    update marathon.agenda_tarifas set vigente=false where plan_id=t.plan_id and vigente and desde>=t.fecha;
    insert into marathon.agenda_tarifas(plan_id,desde,importe,request_id,created_by)values(t.plan_id,t.fecha,fee,p_request_id,auth.uid());
    for qrow in select *from marathon.agenda_cuotas q where q.plan_id=t.plan_id and q.hasta>t.fecha order by q.fecha for update loop
     if marathon.agenda_cuota_pagado(qrow.id)>0 or exists(select 1 from marathon.agenda_ajustes a where a.cuota_id=qrow.id)then
      quotes_kept=quotes_kept+1;
     elsif qrow.importe<>fee then
      update marathon.agenda_cuotas set importe=fee where id=qrow.id;
      insert into marathon.operation_audit(request_id,actor,entity,entity_id,action,before_data,after_data)
      select p_request_id,auth.uid(),'agenda-cuota',qrow.id::text,'importe_desde_turno',to_jsonb(qrow),to_jsonb(x)from marathon.agenda_cuotas x where x.id=qrow.id;
      quotes_changed=quotes_changed+1;
     end if;
    end loop;
   end if;
   update marathon.agenda_planes set updated_at=now()where id=t.plan_id;
   -- Comprobar semanas representativas y cada cambio futuro de ocupación conocido.
   for candidate in
    with boundaries as(
     select generate_series(least(t.fecha,new_date),greatest(t.fecha,new_date)+42,interval '1 day')::date d
     union select x.fecha from marathon.turnos x where x.fecha>=least(t.fecha,new_date)and(x.dni=t.dni or x.profesional_id in(select ah.profesional_id from marathon.agenda_horarios ah where ah.id::text in(select value from jsonb_each_text(maps))))
     union select x.desde from marathon.agenda_horarios x where x.desde>=least(t.fecha,new_date)
     union select x.hasta from marathon.agenda_horarios x where x.hasta>=least(t.fecha,new_date)
     union select x.desde from marathon.agenda_pausas x where x.desde>=least(t.fecha,new_date)
     union select x.hasta from marathon.agenda_pausas x where x.hasta>=least(t.fecha,new_date)
    )select distinct h.id,h.desde,h.hasta,h.dia,(b.d+((h.dia-extract(dow from b.d)::int+7)%7))fecha
    from marathon.agenda_horarios h cross join boundaries b where h.id::text in(select value from jsonb_each_text(maps))
   loop
    if candidate.fecha<candidate.desde or(candidate.hasta is not null and candidate.fecha>=candidate.hasta)or(p.baja is not null and candidate.fecha>=p.baja)then continue;end if;
    select a.*into occ from marathon.agenda_pool(candidate.fecha)a where a.plan_id=t.plan_id and(a.id='H-'||candidate.id::text||'-'||candidate.fecha::text or a.id in(select x.id from marathon.turnos x where x.horario_id=candidate.id and x.fecha_habitual=candidate.fecha))limit 1;
    if not found then continue;end if;
    slot=marathon.agenda_cupo(occ.fecha,occ.sede,occ.profesional_id,occ.terapia_id,occ.hora,null,occ.id);
    if coalesce((slot->>'blocked')::boolean,true)or coalesce((slot->>'remaining')::int,0)<1 or exists(select 1 from marathon.agenda_pool(occ.fecha)a where a.dni=t.dni and a.id<>occ.id and a.hora<occ.hora+make_interval(mins=>occ.duracion_min)and occ.hora<a.hora+make_interval(mins=>a.duracion_min))then raise exception 'La repetición futura entra en conflicto el %. No se guardó el cambio.',occ.fecha using errcode='PT409';end if;
   end loop;
  end if;
 end if;
 if t.plan_id is not null and scope='following'then insert into marathon.operation_audit(request_id,actor,entity,entity_id,action,before_data,after_data)
 select p_request_id,auth.uid(),'agenda-plan',t.plan_id::text,'turn_series_'||kind,before_plan,to_jsonb(x)||jsonb_build_object('motivo',reason,'desde',t.fecha,'horarios',maps)from marathon.agenda_planes x where x.id=t.plan_id;
 else insert into marathon.operation_audit(request_id,actor,entity,entity_id,action,after_data)values(p_request_id,auth.uid(),'turn',t.id,'turn_series_'||kind,jsonb_build_object('desde',t.fecha,'alcance',scope,'motivo',reason));end if;
 result=jsonb_build_object('ids',ids,'count',count_changed,'recurring',t.plan_id is not null and scope='following','cuotas_actualizadas',quotes_changed,'cuotas_conservadas',quotes_kept,'message',case when kind='cancel'then count_changed||' turno(s) cancelados.'else count_changed||' turno(s) editados.'end||case when t.plan_id is not null and scope='following'then case when kind='cancel'then' La asignación quedó dada de baja desde la fecha elegida.'else' Se actualizó también la repetición futura.'end else''end||case when quotes_changed>0 then' Se actualizó la cuota sin pagos.'else''end||case when quotes_kept>0 then' Las cuotas con pagos o ajustes conservaron su importe; el nuevo valor se aplica a las próximas.'else''end);
 update marathon.solicitudes set resultado=result where id=p_request_id;return result;
end$function$
;
CREATE OR REPLACE FUNCTION marathon.agenda_turno_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p marathon.agenda_planes%rowtype;q jsonb;a uuid;begin
 perform pg_advisory_xact_lock(hashtextextended('marathon:master-write:v1',0));
 if tg_op='INSERT' and new.recovered_from is not null and new.plan_id is null then
  select t.plan_id,t.terapia_override into new.plan_id,new.terapia_override from marathon.turnos t where t.id=new.recovered_from;
  if new.plan_id is not null then new.fecha_habitual=new.fecha;end if;
 end if;
 if new.plan_id is not null then
  select * into strict p from marathon.agenda_planes where id=new.plan_id for update;
  if new.dni<>p.dni or new.terapia_id<>coalesce(new.terapia_override,(select h.terapia_override from marathon.agenda_horarios h where h.id=new.horario_id and h.plan_id=p.id),p.terapia_id) then raise sqlstate '22023' using message='El turno no corresponde al tratamiento.';end if;
  if new.estado in('PRESENTE','AUSENTE') and marathon.agenda_pausado(p.id,new.fecha) then raise sqlstate '22023' using message='El tratamiento está pausado; conserva su lugar y no registra faltas.';end if;
  if new.estado='PRESENTE' and p.baja is not null and new.fecha>=p.baja then raise sqlstate '22023' using message='El tratamiento está dado de baja.';end if;
  if new.estado='PENDIENTE'and p.modalidad='sessions'and marathon.agenda_presentes(p.id)-(case when tg_op='UPDATE'and old.estado='PRESENTE'then 1 else 0 end)>=marathon.agenda_total(p.id)then raise sqlstate '22023'using message='Las sesiones están completas. Registrá una nueva cantidad.';end if;
  if new.estado='PRESENTE' and p.modalidad='sessions' then
   select x.id into a from marathon.agenda_autorizaciones x where x.plan_id=p.id and (select count(*) from marathon.turnos t where t.autorizacion_id=x.id and t.estado='PRESENTE' and t.id<>new.id)<x.cantidad order by x.fecha,x.created_at,x.id limit 1;
   if a is null then raise sqlstate '22023' using message='Se completaron las sesiones autorizadas. Registrá una nueva cantidad.';end if;new.autorizacion_id=a;
  elsif new.estado<>'PRESENTE' then new.autorizacion_id=null;end if;
 end if;
 if new.estado<>'CANCELADO' and (tg_op='INSERT' or old.estado='CANCELADO' or (old.fecha,old.hora,old.sede,old.profesional_id,old.terapia_id) is distinct from(new.fecha,new.hora,new.sede,new.profesional_id,new.terapia_id)) then
  if exists(select 1 from marathon.agenda_pool(new.fecha)x where x.dni=new.dni and x.id<>new.id and not(x.plan_id is not distinct from new.plan_id and new.horario_id is not null and x.id='H-'||new.horario_id::text||'-'||new.fecha_habitual::text) and x.hora<new.hora+make_interval(mins=>new.duracion_min) and new.hora<x.hora+make_interval(mins=>x.duracion_min)) then raise sqlstate '22023' using message='El paciente ya tiene atención o un lugar reservado en ese horario.';end if;
  q=marathon.agenda_cupo(new.fecha,new.sede,new.profesional_id,new.terapia_id,new.hora,new.plan_id,new.id);
  if coalesce((q->>'remaining')::int,0)<1 or coalesce((q->>'blocked')::boolean,true) then raise sqlstate '22023' using message='El horario no tiene cupo o dejó de estar habilitado.';end if;
 end if;return new;
end$function$
;
revoke all on function marathon.turn_series_run(text,jsonb),marathon.agenda_virtual(date),marathon.agenda_turno_guard()from public,anon,authenticated;
do $guard$declare actual jsonb;begin select snapshot into actual from(select jsonb_object_agg(name,jsonb_build_object('count',n,'hash',h))snapshot from(select 'agenda_ajustes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_ajustes" x union all select 'agenda_autorizaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_autorizaciones" x union all select 'agenda_cuotas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_cuotas" x union all select 'agenda_horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_horarios" x union all select 'agenda_pausas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_pausas" x union all select 'agenda_periodos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_periodos" x union all select 'agenda_planes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_planes" x union all select 'agenda_tarifas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."agenda_tarifas" x union all select 'anticipo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."anticipo_eventos" x union all select 'anticipos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."anticipos" x union all select 'app_users'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."app_users" x union all select 'attendance_settings'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."attendance_settings" x union all select 'attendance_system_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."attendance_system_audit" x union all select 'bonos_serie'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."bonos_serie" x union all select 'documentos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."documentos" x union all select 'espera'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."espera" x union all select 'horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."horarios" x union all select 'informacion_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."informacion_terapias" x union all select 'master_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."master_audit" x union all select 'movimientos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."movimientos" x union all select 'obras_sociales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."obras_sociales" x union all select 'operation_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."operation_audit" x union all select 'ortopedia_operaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."ortopedia_operaciones" x union all select 'pacientes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."pacientes" x union all select 'productos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."productos" x union all select 'profesional_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."profesional_terapias" x union all select 'profesionales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'[]')::text)h from marathon."profesionales" x union all select 'saldo_ajustes_sesion'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'terapia_override')order by (to_jsonb(x)-'terapia_override')::text collate "C"),'